query:
fragment researchAggregation on ResearchDocumentResults {
  count
  aggregations {
    name
    results {
      value
      displayName
      count
      __typename
    }
    __typename
  }
  __typename
}

query fullCompanyDetailsQuery($ticker: [String], $initialAggregations: [ResearchAggregationDetails], $initialQueryNode: [ResearchQueryNode]) {
  companyService {
    companies(q: {queryNode: {operator: EQUALS, item: ID, values: $ticker}}) {
      results {
        id
        displayName
        bloombergTicker
        ricCode {
          ticker
          exchange
          __typename
        }
        coveringAnalysts {
          sid
          equity
          credit
          private
          email
          displayName
          phoneNumber
          photo {
            type
            focalPointY
            height
            focalPointX
            url
            width
            __typename
          }
          __typename
        }
        sector {
          id
          displayName
          __typename
        }
        region {
          id
          displayName
          __typename
        }
        credit
        equity
        privateCompany
        equityRating
        creditRating
        targetPrice {
          formattedDate
          date
          value
          formattedValue
          __typename
        }
        coverage {
          results {
            priceTargetUpside
            fiscalYearEnd
            priceTargetEndDate
            __typename
          }
          __typename
        }
        baseAggregations: research(
          q: {queryNode: {operator: AND, children: $initialQueryNode}, options: {aggregations: $initialAggregations, count: 20, start: 1, sortOrder: PUBLICATION_DATE, sortDirection: DESCENDING}}
        ) {
          count
          ...researchAggregation
          __typename
        }
        __typename
        equityModel: research(
          q: {businessGroupClassification: RESEARCH, options: {sortOrder: PUBLICATION_DATE, sortDirection: DESCENDING, start: 1, count: 1}, queryNode: {operator: AND, children: [{operator: AND, children: [{item: COMPANY, operator: EQUALS, values: $ticker}, {item: KEYWORD, operator: EQUALS, values: "WORKINGMODEL"}]}, {operator: AND, children: [{operator: NOT, children: [{item: DOCUMENT_TYPE, operator: EQUALS, values: ["VIDEO"]}]}, {operator: NOT, children: [{item: DOCUMENT_TYPE, operator: EQUALS, values: ["AUDIO"]}]}, {item: SOURCE_SYSTEM, operator: NOT_EQUALS, values: "GPSWebWebmail"}]}]}}
        ) {
          results {
            id
            publicationDate
            analysts {
              results {
                sid
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
      }
      __typename
    }
    __typename
  }
}
